def test_start_and_stop_timer():
    """
    This test case checks if the Timer object can start and stop correctly.
    """

    # Constants
    TIMER_NAME = "Test_Timer"
    INITIAL_TEXT = "Timer {name} started."
    TEXT_AFTER_TIMER_STOP = "{milliseconds} ms have passed"

    # Setup
    my_timer = Timer(TIMER_NAME, INITIAL_TEXT, TEXT_AFTER_TIMER_STOP)

    # Execution
    my_timer.start()  # Start the timer
    assert my_timer._start_time is not None, "Timer did not start"

    time.sleep(1)  # Wait for 1 second

    elapsed_time = my_timer.stop()  # Stop the timer
    
    # Assertion
    assert my_timer._start_time is None, "Timer did not stop"
    assert elapsed_time >= 1000, "Elapsed time less than 1 second"
    assert my_timer.last == elapsed_time, "Elapsed time not correctly stored"
    assert my_timer.timers.get(TIMER_NAME) == elapsed_time, "Timer result not correctly added to timers"

